import { NextResponse } from 'next/server';
import { handleApiError } from '@/lib/rollbar/api-error-handler';

export async function GET(request: Request) {
    try {
        throw new Error('FINAL_VERIFICATION_ERROR: Testing with new Server Token privileges.');
    } catch (error: any) {
        return await handleApiError(error, request, {
            verification: true,
            tokenType: 'post_server_item'
        });
    }
}
